36	/**
37	 * Calculates the cost for a Google AI Studio API call.
38	 *
39	 * Handles tiered pricing for models where cost varies by prompt size.
40	 * For example, Gemini Pro models have higher rates for prompts >200k tokens.
41	 *
42	 * @param modelName - The name of the model used
43	 * @param config - Provider configuration (may contain custom cost override)
44	 * @param promptTokens - Number of tokens in the prompt
45	 * @param completionTokens - Number of tokens in the completion
46	 * @returns The calculated cost in dollars, or undefined if it cannot be calculated
47	 */
48	export function calculateGoogleCost(
49	  modelName: string,
50	  config: ProviderConfig,
51	  promptTokens?: number,
52	  completionTokens?: number,
53	): number | undefined {
54	  // Check for tiered pricing (higher rates above token threshold)
55	  if (promptTokens != null && completionTokens != null) {
56	    const model = GOOGLE_MODELS.find((m) => m.id === modelName);
57	    if (model?.tieredCost && promptTokens > model.tieredCost.threshold) {
58	      const inputCost = config.cost ?? model.tieredCost.above.input;
59	      const outputCost = config.cost ?? model.tieredCost.above.output;
60	      const cost = inputCost * promptTokens + outputCost * completionTokens;
61	      return cost;
62	    }
63	  }
64	
65	  // Use standard calculation for non-tiered pricing
66	  return calculateCost(modelName, config, promptTokens, completionTokens, GOOGLE_MODELS);
67	}
